import os
import subprocess
import sys
import re


def _template(value, vars):
    def replace(match):
        key = match.group(1)
        return str(vars.get(key, os.environ.get(key, "")))
    return re.sub(r"{{\s*\.([A-Za-z_][\w]*)\s*}}", replace, str(value))


def _commands(task):
    if isinstance(task, str):
        return [task]
    if isinstance(task, list):
        return task
    task = task or {}
    cmds = task.get("cmds", []) or []
    if not cmds and task.get("cmd"):
        cmds = [task["cmd"]]
    return cmds


def _summary_value(value):
    if value is None:
        return ""
    if isinstance(value, bool):
        return str(value).lower()
    if isinstance(value, (list, tuple)):
        return "[" + " ".join(map(str, value)) + "]"
    if isinstance(value, dict):
        return "map[" + " ".join(f"{k}:{v}" for k, v in value.items()) + "]"
    return str(value)


def show_summary(config, name, taskfile="", cwd=None):
    """Print the reference-style summary for one normalized task."""
    tasks = config.get("tasks") or {}
    task = tasks.get(name)
    if task is None:
        print(f'task: Task "{name}" does not exist', file=sys.stderr)
        return 200
    obj = task if isinstance(task, dict) else {}
    vars = dict(config.get("vars") or {})
    vars.update(obj.get("vars") or {})
    taskfile_path = os.path.abspath(taskfile) if taskfile and taskfile != "stdin" else "stdin"
    template_vars = dict(vars)
    template_vars.update({
        "TASK": name,
        "ROOT_DIR": os.path.abspath(cwd or os.path.dirname(taskfile_path)),
        "TASKFILE": taskfile_path,
        "ROOT_TASKFILE": taskfile_path,
        "TASKFILE_DIR": os.path.dirname(taskfile_path),
    })
    print(f"task: {name}")
    print()
    desc = obj.get("summary") or obj.get("desc", "")
    print(_template(desc, template_vars) if desc else "(task does not have description or summary)")
    print()
    if vars:
        print("vars:")
        for key, value in vars.items():
            # Task's summary uses YAML-compatible quoted strings for scalars.
            val = '"' + _summary_value(value).replace('\\', '\\\\').replace('"', '\\"') + '"'
            print(f"  {key}: {val}")
        print()
    deps = obj.get("deps") or []
    if isinstance(deps, str):
        deps = [deps]
    if deps:
        print("dependencies:")
        for dep in deps:
            if isinstance(dep, dict):
                dep = dep.get("task", "")
            print(f" - {dep}")
        print()
    cmds = _commands(task)
    rendered = []
    for command in cmds:
        if isinstance(command, dict):
            command = command.get("cmd", "")
        if command:
            rendered.append(_template(command, template_vars))
    if rendered:
        print("commands:")
        for command in rendered:
            print(f" - {command}")
    return 0


def check_status(config, name, cwd=None):
    """Return success only when status commands all report the task current."""
    task = (config.get("tasks") or {}).get(name)
    if task is None:
        print(f'task: Task "{name}" does not exist', file=sys.stderr)
        return 200
    task = task if isinstance(task, dict) else {}
    checks = task.get("status") or []
    if isinstance(checks, str):
        checks = [checks]
    env = os.environ.copy()
    for key, value in (config.get("vars") or {}).items():
        env[str(key)] = str(value)
    for check in checks:
        try:
            if subprocess.run(str(check), shell=True, cwd=cwd, env=env,
                              stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).returncode:
                break
        except OSError:
            break
    else:
        if checks:
            return 0
    print(f'task: Task "{name}" is not up-to-date', file=sys.stderr)
    return 1
"}

